/**
 * Get a random question for a given difficulty, avoiding recently used questions.
 * @param {string} difficulty - 'easy' | 'medium' | 'hard' | 'nightmare'
 * @param {string[]} usedIndexes - array of question indexes already used this game
 */
export function getRandomQuestion(difficulty = 'medium', usedIndexes = []) {
  const pool = questionBank[difficulty] || questionBank.medium;
  const available = pool.filter((_, i) => !usedIndexes.includes(i));

  // If all questions used, reset and use full pool
  const source = available.length > 0 ? available : pool;
  const question = source[Math.floor(Math.random() * source.length)];

  // Convert to the expected format
  return {
    question: question.question,
    optionA: question.optionA,
    optionB: question.optionB,
    consequences: {
      A: question.consequenceA,
      B: question.consequenceB
    },
    dangerLevels: {
      A: question.dangerA,
      B: question.dangerB
    }
  };
}
